import numpy as np

def process_audio_signal(signal: np.ndarray, sample_rate: int = 44100) -> np.ndarray:
    # Normalisasi sinyal ke [-1.0, 1.0]
    max_val = np.max(np.abs(signal))
    normalized = signal / (max_val + 1e-8)
    return normalized.astype(np.float32)

import numpy as np

def evaluate_metric(reference: np.ndarray, processed: np.ndarray) -> float:
    # Signal-to-Noise Ratio (SNR) in dB
    noise = reference - processed
    p_sig = np.mean(reference ** 2)
    p_noise = np.mean(noise ** 2)
    if p_noise < 1e-10:
        return 100.0
    return float(10 * np.log10(p_sig / p_noise))
